export class RxNormDatabaseService {
  public static findByRxcui(rxcui: string): MasterRxNormEntry | undefined {
    return RXNORM_COMPREHENSIVE_DATABASE.find((r) => r.rxcui === rxcui.trim());
  }

  public static findByNdc(ndc: string): MasterRxNormEntry | undefined {
    return RXNORM_COMPREHENSIVE_DATABASE.find((r) => r.ndc11.replace(/-/g, '') === ndc.replace(/-/g, ''));
  }
}
